from datetime import datetime

# Re-fetch all received payment requests (all statuses) and verify target set still pending and matches criteria

def parse_iso(dt_str):
    if not dt_str:
        return None
    s = dt_str.replace('Z','')
    try:
        return datetime.fromisoformat(s)
    except Exception:
        return datetime.strptime(s.split('.')[0], '%Y-%m-%dT%H:%M:%S')

# Fetch all received payment requests (no status filter)
all_received = []
pi = 0
pl = 20
while True:
    page = apis.venmo.show_received_payment_requests(access_token=venmo_token, page_index=pi, page_limit=pl)
    if not page:
        break
    all_received.extend(page)
    pi += 1

print('Total received payment requests (all statuses):', len(all_received))

# Build lookup by id
by_id = {pr.get('payment_request_id'): pr for pr in all_received}

month_ok = {}
rows = []

# month_start and next_month_start should exist from earlier code
month_start_dt = month_start
next_month_start_dt = next_month_start

for pid in TARGET_PAYMENT_REQUEST_IDS:
    pr = by_id.get(pid)
    rows.append({
        'payment_request_id': pid,
        'exists_in_received_list': pr is not None,
        'status': pr.get('status') if pr else None,
        'created_at': pr.get('created_at') if pr else None,
        'created_in_month': (parse_iso(pr.get('created_at'))>=month_start_dt and parse_iso(pr.get('created_at'))<next_month_start_dt) if pr else None,
        'sender_email': (pr.get('sender') or {}).get('email') if pr else None,
        'sender_is_roommate': ((pr.get('sender') or {}).get('email') or '').lower() in {e.lower() for e in venmo_mapped_emails} if pr else None
    })

# Some APIs may not include status field; verify by checking approved_at/denied_at presence
for r in rows:
    if r['status'] is None:
        pid = r['payment_request_id']
        pr = by_id.get(pid)
        if pr:
            approved_at = pr.get('approved_at')
            denied_at = pr.get('denied_at')
            if approved_at:
                r['status'] = 'approved'
            elif denied_at:
                r['status'] = 'denied'
            else:
                r['status'] = 'pending'

print('Verification table for target payment_request_ids:')
for r in rows:
    print(r)

# Ensure all are pending
pending_ids = [r['payment_request_id'] for r in rows if r['status']=='pending']
print('Pending among target ids:', pending_ids)
print('Non-pending among target ids:', [r['payment_request_id'] for r in rows if r['status']!='pending'])

# Derive action target set = those pending
ACTION_PAYMENT_REQUEST_IDS = pending_ids
print('ACTION_PAYMENT_REQUEST_IDS count:', len(ACTION_PAYMENT_REQUEST_IDS))

